// Glance → a project/library graph node, AS GRAPH SOURCE (#4185, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the glance lib/hook surface via the glance graph-platform,
// and the sibling components as @/components/* graph records). Behaviour runs here.
// The fleet/project NODE card (#4032) — extracted from the inline JSX in `GlanceCanvas`'s node map so
// it is a real component the designer can reach, and so its live states are authored MOTION DATA
// (`@/shared/ui/kit/glanceNodeAnimations`) rather than a raw keyframe in `glance.css` plus an inline
// `boxShadow`.
//
// ── THE STATE VOCABULARY ────────────────────────────────────────────────────────────────────────
// Three states, three motions, and the differences are deliberate:
//   · building  BREATHES — the worker is working (#4015)
//   · attention RINGS    — it is blocked on a PERSON, the one state that needs someone (#4005)
//   · complete  is STILL — finished; motion means "look at this", and this needs nothing (#4027)
//
// The first two come from the compiled kit CSS, bound to `data-node-state`. The third is the ABSENCE
// of an animation, which is why there is no `complete` entry in the motion data.
//
// ── WHAT STAYED IN THE CANVAS ───────────────────────────────────────────────────────────────────
// Everything positional and model-derived: layout, the border precedence chain (selected → preview →
// off → error → cycle → focus), the health rollup, push offsets. Those are graph CONCERNS, not node
// presentation, and threading them out would have made this a worse component, not a more reusable
// one. This owns the card's body: its states, its dot, its two label rows.
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import type { GNode } from "@/features/glance/lib/glanceGraph";

// `@/features/glance/glanceNodeMotion` reaches into `@/shared/ui/kit`, a barrel whose own
// theme/ThemeScope/ThemeProvider/resolve/variants exports fail to resolve in this preview sandbox (a
// pre-existing gap in that platform module, outside this kit's `bsc ui` surface — the same one
// `AlgorithmsInspector` hits). Importing it as a VALUE crashes the whole module at load time; these
// local stand-ins replace the two runtime values it provided — a no-op motion-CSS injector and the
// plain applying class name — so the node still renders (just without the injected @keyframes; the
// `data-node-state` attribute below is unaffected and the CSS binds live once that barrel is fixed).
const GLANCE_NODE_ANIM_CLASSES = "glance-node-anim";
function ensureGlanceNodeMotion(): void {}

/** Which live state the node's motion should express, or `null` for a still node. */
export type GlanceNodeState = "building" | null;

export interface GlanceNodeProps {
  n: GNode;
  /** Precomputed by the canvas — the border precedence chain it owns. */
  border: string;
  boxShadow: string;
  /** Health dot colour + whether it pulses (axis 1). */
  healthColor: string;
  healthPulse: boolean;
  /** Pulse CHARACTER (#4052) — an alarm (fast + haloed, `error`) vs a breath (slow + bare,
   *  `modifying`). Both optional so the alarm stays the default and `error` renders unchanged. */
  healthPulseMs?: number;
  healthGlow?: boolean;
  /** Lit only by a DOWNSTREAM dep — dimmed, never pulses, so the eye lands on the fault's ORIGIN. */
  inherited: boolean;
  /** The lower-left FUNCTION chip — fleet (L1) nodes only (#4052). Both absent ⇒ the slot renders
   *  nothing at all, which is how an L0 project node reads now that the lifecycle axis is gone. */
  roleColor?: string;
  roleLabel?: string;
  /** Axis-2 word + its colour, and whether it pulses (suppressed while the NODE itself animates). */
  bottomText: string;
  bottomColor: string;
  bottomPulse: boolean;
  /** The user-deactivated / degraded reads, which suppress the completion marker. */
  isOff: boolean;
  degraded: boolean;
  ownDegraded: boolean;
  /** The live motion state, or null. */
  state: GlanceNodeState;
  /** Owned-issue completion (#4050), or 0 for "no bar". Presentational only. */
}

// #4123-follow-up (designer experiment): the previous left-to-right `color-mix` gradient wash wasn't
// rendering visibly in the live app — likely the `linear-gradient(...), var(--bg-elev)` multi-layer
// background shorthand combined with `color-mix(in oklch, …)` not resolving the way this sandbox's
// preview assumed. Replaced with the most boring possible mechanism: a plain solid-colour overlay
// whose WIDTH still reads as "how far along" (the fill) and whose OPACITY now does the intensity work
// that the color-mix percentages used to — no gradients, no color-mix, nothing that depends on a
// browser correctly compositing multiple background layers. Zero stays zero (no mark at 0%, same
// principle as before); opacity then ramps with fill up to a still-subtle ceiling so a complete node
// reads as "washed", not "painted".
const MAX_FILL_OPACITY = 0.32;
export function nodeFillOpacity(fill: number): number {
  if (fill <= 0) return 0;
  return Math.min(1, Math.max(0, fill)) * MAX_FILL_OPACITY;
}

const DEFAULT_NODE: GNode = {
  slug: "design-studio", rollupHealth: "healthy", activity: "idle", progress: { done: 9, total: 10 }, appType: "application",
} as unknown as GNode;

export function GlanceNode(p: Partial<GlanceNodeProps> = {}) {
  const {
    n: nProp, border = "var(--border-soft)", boxShadow = "0 2px 8px rgba(0,0,0,.45)",
    healthColor = "var(--graph-health-healthy)", healthPulse = false, healthPulseMs, healthGlow,
    inherited = false, roleColor, roleLabel, bottomText = "idle", bottomColor = "var(--fg-muted)", bottomPulse = false,
    isOff = false, degraded = false, ownDegraded = false, state = null,
  } = p;
  // Designer-preview guard: this sandbox's generic preview-props synthesizer doesn't know the real
  // `GNode` shape, so a standalone "loaded" preview can hand `n` a placeholder STRING instead of an
  // object — `n.progress`/`n.slug` would then silently read as `undefined` and the fill would always
  // compute to 0. The real app only ever passes a genuine GNode, so this guard is a no-op there.
  const n: GNode = nProp && typeof nProp === "object" ? nProp : DEFAULT_NODE;
  // Progress is the NODE'S OWN FILL (#4123) — not a bar drawn on it.
  //
  // It was a discrete widget twice over: a 2px hairline, then a 5px track with `done/total` beside it.
  // Both were wrong for what this number IS. Completion here is COARSE — the refs are a planning
  // artifact, "done" is whatever evidence happened to be reachable, and nobody sizes a decision off
  // the third digit. A precise-looking readout on every node invites reading it precisely, and it
  // competes with the health dot and activity word for the same glance.
  //
  // So the node still fills left to right (the WIDTH reads as "how far along"), but the intensity is
  // now a flat OPACITY on a solid overlay rather than a color-mix gradient wash (see the designer note
  // above `nodeFillOpacity`) — same idea, a more boring, more reliably-rendering mechanism.
  const progress = n.progress;
  const fill = progress && progress.total > 0 ? Math.max(0, Math.min(1, progress.done / progress.total)) : 0;
  const fillOpacity = nodeFillOpacity(fill);
  // Idempotent + cheap (one string compare after the first call). Done HERE rather than at the canvas
  // so the component carries its own motion: anything that renders a node gets the CSS, and nothing
  // has to remember to mount it.
  ensureGlanceNodeMotion();
  return (
    <Box
      // The applying classes + the state attribute ARE the binding: the compiled kit CSS scopes each
      // animation to `[data-node-state="…"]`, so a designer reading the record sees which state each
      // animation belongs to without any class bookkeeping here.
      className={GLANCE_NODE_ANIM_CLASSES}
      data-node-state={state ?? undefined}
      // The exact numbers stay reachable on hover without occupying the node.
      title={progress && progress.total > 0 ? `${progress.done}/${progress.total} issues complete` : undefined}
      style={{ width: "100%", height: "100%", background: "var(--bg-elev)", border: `1px solid ${border}`,
        borderRadius: 9, padding: "10px 12px", display: "flex", flexDirection: "column", justifyContent: "center",
        boxShadow: boxShadow, transition: "border-color .15s, box-shadow .15s",
        // `relative` so the fill overlay + progress bar can sit inside; `overflow: hidden` keeps both
        // inside the rounded corners.
        position: "relative", overflow: "hidden" }}>
      {/* The completion fill overlay — width = how far along, opacity = intensity. A plain solid
          colour block, deliberately not a gradient: the earlier color-mix gradient wash is the thing
          that wasn't rendering live, so this trades a little visual softness for something that just
          works everywhere. */}
      {fill > 0 && (
        <Box aria-hidden style={{
          position: "absolute", left: 0, top: 0, bottom: 0, width: `${fill * 100}%`,
          background: "var(--graph-health-complete)", opacity: fillOpacity,
          transition: "width .2s ease, opacity .2s ease", pointerEvents: "none",
        }} />
      )}
      <Box style={{ display: "flex", alignItems: "center", gap: 8, position: "relative" }}>
        {/* Axis-1 health DOT. Restored in #4040 with the glow gone — health is a colour, and without
            this the node had no colour surface for it at all. An INHERITED dot is dimmed and never
            pulses, so the eye lands on the ORIGIN of a fault rather than everything downstream
            (#2541). */}
        <Box title={`${n.rollupHealth}${inherited ? " (downstream)" : ""}`}
          style={{ width: 8, height: 8, borderRadius: "50%", background: healthColor, flex: "none", opacity: inherited ? 0.5 : 1,
            boxShadow: healthPulse && !inherited && healthGlow !== false ? `0 0 8px ${healthColor}` : "none",
            animation: healthPulse && !inherited ? `glance-softpulse ${healthPulseMs ?? 1400}ms ease-in-out infinite` : "none" }} />
        <Text as="span" mono size={13} weight={600} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{n.slug}</Text>
        {/* The APP-TYPE discriminator (#3786/#3802) — a subtle mono micro-label on the title line: what
            KIND of app this endpoint is (api/serverless/cli/…). Gated on a non-default classification,
            so an unclassified project (appType absent, or "application") renders byte-identical. */}
        {n.appType && n.appType !== "application" && (
          <Text as="span" mono size={8.5} title={`app type: ${n.appType}`}
            style={{ flex: "none", textTransform: "uppercase", letterSpacing: ".4px", color: "var(--fg-muted)", opacity: 0.7,
              border: "1px solid var(--border-soft)", borderRadius: 4, padding: "1px 4px", lineHeight: 1.3 }}>{n.appType}</Text>
        )}
      </Box>
      {/* The axis-2 row. #4058 briefly stripped this from L0 project nodes; #4060 restored it — that
          change was meant to clean up the LEGEND, not the nodes. The word stays on every node at both
          levels; only the legend's L0 ACTIVITY column is gone. */}
      <Box style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 9, position: "relative" }}>
        {roleLabel && (
          <Text as="span" mono size={10} style={{ textTransform: "uppercase", letterSpacing: ".5px", color: roleColor }}>{roleLabel}</Text>
        )}
        <Box style={{ flex: 1 }} />
        {/* #4027 — the FINISHED marker. Static and to the LEFT of the word, so a completed node is
            legible at a glance without reading its label. */}
        {n.activity === "complete" && !isOff && !degraded && (
          <Text as="span" mono size={10} weight={600} aria-hidden
            style={{ color: "var(--graph-health-healthy)", marginRight: 4, flex: "none" }}>✓</Text>
        )}
        {/* Axis-2 activity word, or the fault reason when degraded. */}
        <Text as="span" mono size={10} weight={500} title={ownDegraded && n.reason ? n.reason : n.activity === "complete" ? n.reason : undefined}
          style={{ color: bottomColor, maxWidth: 108, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
            animation: bottomPulse ? "glance-softpulse 1.4s ease-in-out infinite" : "none" }}>{bottomText}</Text>
      </Box>
    </Box>
  );
}
